-- V1__init_schema.sql
--
-- Initial ThreadHub schema. This is the schema Hibernate generated for the
-- User, Community and CommunityMember entities while spring.jpa.hibernate.ddl-auto=update was
-- in use; it is now owned by Flyway and Hibernate only validates against it.
--
-- Table names, column names, types, lengths, nullability and constraints mirror the JPA mappings:
--   * id columns use `bigint generated by default as identity` (GenerationType.IDENTITY),
--   * timestamps are `timestamp(6)` and NOT NULL (@CreationTimestamp / @UpdateTimestamp),
--   * enum role is stored as text (@Enumerated(EnumType.STRING)) with a matching CHECK constraint,
--   * unique constraints and foreign keys follow the entity/join-column names.
--
-- Never edit this file once it has been applied to a database. Schema changes go into a new
-- versioned migration (for example V2__add_posts.sql).

CREATE TABLE users (
    id         bigint GENERATED BY DEFAULT AS IDENTITY,
    created_at timestamp(6) NOT NULL,
    email      varchar(255) NOT NULL,
    password   varchar(255) NOT NULL,
    updated_at timestamp(6) NOT NULL,
    username   varchar(255) NOT NULL,
    CONSTRAINT users_pkey PRIMARY KEY (id),
    CONSTRAINT uk_users_username UNIQUE (username),
    CONSTRAINT uk_users_email UNIQUE (email)
);

CREATE TABLE communities (
    id          bigint GENERATED BY DEFAULT AS IDENTITY,
    created_at  timestamp(6) NOT NULL,
    description varchar(1000),
    name        varchar(255) NOT NULL,
    updated_at  timestamp(6) NOT NULL,
    owner_id    bigint NOT NULL,
    CONSTRAINT communities_pkey PRIMARY KEY (id),
    CONSTRAINT uk_communities_name UNIQUE (name),
    CONSTRAINT fk_communities_owner FOREIGN KEY (owner_id) REFERENCES users (id)
);

CREATE TABLE community_members (
    id           bigint GENERATED BY DEFAULT AS IDENTITY,
    joined_at    timestamp(6) NOT NULL,
    role         varchar(255) NOT NULL,
    community_id bigint NOT NULL,
    user_id      bigint NOT NULL,
    CONSTRAINT community_members_pkey PRIMARY KEY (id),
    CONSTRAINT uk_user_community UNIQUE (user_id, community_id),
    CONSTRAINT community_members_role_check CHECK (role IN ('OWNER', 'MEMBER')),
    CONSTRAINT fk_community_members_community FOREIGN KEY (community_id) REFERENCES communities (id),
    CONSTRAINT fk_community_members_user FOREIGN KEY (user_id) REFERENCES users (id)
);
